const tavily = $input.first().json || {};
const results = tavily.results || [];

function parseTitle(raw) {
  if (!raw) return null;
  const clean = raw.replace(/\s*\|\s*LinkedIn\.?$/i, '').trim();
  const parts = clean.split(/\s+-\s+/);
  const fullName = parts[0]?.trim();
  const rest = parts.slice(1).join(' - ');
  let title = '', company = '';
  const atMatch = rest?.match(/(.+?)\s+at\s+(.+)/i);
  if (atMatch) {
    title = atMatch[1].trim();
    company = atMatch[2].trim().replace(/\s+-\s+.*$/, '').trim();
  } else if (rest) {
    title = rest.trim();
  }
  return { fullName, title, company };
}

const profiles = [];
const seen = new Set();

for (const r of results) {

  if (!r.url?.includes('linkedin.com/in/')) continue;
  if (seen.has(r.url)) continue;
  const parsed = parseTitle(r.title);
  if (!parsed || !parsed.fullName || parsed.fullName.length < 2) continue;
  seen.add(r.url);
  profiles.push({
    full_name: parsed.fullName,
    company: parsed.company || '',
    role: parsed.title || '',
    email: '',
    linkedin_url: r.url.split('?')[0].replace(/\/$/, ''),
    location: '',
    summary: (r.content || r.title || '').slice(0, 300)
  });
}

return [{ json: { data: profiles, count: profiles.length, source: 'tavily' } }];

